import { readFile, readdir, writeFile } from "node:fs/promises";
const root = new URL("./", import.meta.url);
const names = (await readdir(root)).filter(
  (name) => name.endsWith(".txt") || name === "answer-shapes.json",
);
for (const name of await readdir(new URL("languages/", root))) {
  if (name.endsWith(".txt")) names.push(`languages/${name}`);
}
names.sort();
const files = Object.fromEntries(
  await Promise.all(
    names.map(async (name) => [
      name,
      await readFile(new URL(name, root), "utf8"),
    ]),
  ),
);
await writeFile(
  new URL("../packages/service/src/prompt-bundle.ts", root),
  "// Generated by node prompts/build-bundle.mjs. Edit the public prompt files.\n" +
    "export const promptFiles: Record<string, string> = " +
    JSON.stringify(files, null, 2) +
    ";\n",
);
